const mysql = require('mysql2')


// The communication channel between our Node.js backend and MySQL database.
// const db stores the connection
const db = mysql.createConnection({
    host : 'localhost',
    user : 'root',
    password : '',
    database : 'tms',
});

db.connect((err) => {
    if(err){
        console.error
        ("Database Connection failed",
            // err.message : contains the actual error message generated by the database driver.
             err.message); 
             
        // This stops the callback function.
        return;
    }
    
    console.log
    ("Database Connected Successfully ❤💖")
});

module.exports = db;